	typedef pair<CHRPOS, CHRPOS> BlockInterval;

	// BED coordinates are half-open. Count each covered base once, even when
	// several database annotations cover the same part of the query.
	CHRPOS unionLength(vector<BlockInterval> &intervals)
	{
		if (intervals.empty()) return 0;
		sort(intervals.begin(), intervals.end());
		CHRPOS start = intervals[0].first;
		CHRPOS end = intervals[0].second;
		CHRPOS length = 0;
		for (size_t i = 1; i < intervals.size(); ++i) {
			if (intervals[i].first > end) {
				length += end - start;
				start = intervals[i].first;
				end = intervals[i].second;
			} else {
				end = max(end, intervals[i].second);
			}
		}
		return length + end - start;
	}

	struct BlockedOverlap {
		Record *record;
		CHRPOS blockLength;
		CHRPOS overlapBases;
		vector<BlockInterval> intervals;
	};
